from __future__ import annotations

from orders.application.pricing import discount_for
from orders.controllers.http import Response, not_found
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository


class CustomerInsightsController:
    def __init__(self, orders: InMemoryOrderRepository, customers: InMemoryCustomerRepository) -> None:
        self._orders = orders
        self._customers = customers

    def handle_order_history(self, customer_id: str) -> Response:
        """Get order history for a customer, newest orders first."""
        customer = self._customers.get(customer_id)
        if customer is None:
            return not_found("customer")

        orders = self._orders.list_for_customer(customer_id)
        tier = customer.tier

        order_entries = []
        for order in reversed(orders):
            subtotal = order.subtotal_cents
            discount = discount_for(subtotal, tier)
            total_cents = subtotal - discount
            order_entries.append({
                "order_id": order.order_id,
                "status": order.status,
                "total_cents": total_cents,
            })

        return Response(200, {"customer_id": customer_id, "orders": order_entries})

